css:
.d-sg{width:200px;max-width:100%;height:150px;display:grid;place-items:center;outline:none}
.d-sg-grid{display:grid;grid-template-columns:repeat(3,44px);grid-auto-rows:44px;gap:8px}
.d-sg-cell{display:block;border:1px solid var(--line);border-radius:6px;background:var(--paper)}
.d-sg-grid.is-run .d-sg-cell{animation:d-stagger-grid-pop 280ms cubic-bezier(.34,1.56,.64,1) both}
.d-sg-grid.is-run .d-sg-cell:nth-child(2),.d-sg-grid.is-run .d-sg-cell:nth-child(4),.d-sg-grid.is-run .d-sg-cell:nth-child(6),.d-sg-grid.is-run .d-sg-cell:nth-child(8){animation-delay:120ms}
.d-sg-grid.is-run .d-sg-cell:nth-child(1),.d-sg-grid.is-run .d-sg-cell:nth-child(3),.d-sg-grid.is-run .d-sg-cell:nth-child(7),.d-sg-grid.is-run .d-sg-cell:nth-child(9){animation-delay:280ms}
.d-sg:focus-visible{outline:1px solid var(--ink);outline-offset:6px}
@keyframes d-stagger-grid-pop{from{opacity:0;transform:translateY(6px) scale(.92)}to{opacity:1;transform:none}}

init:
root => {
  const box = root.querySelector('.d-sg');
  const grid = root.querySelector('.d-sg-grid');
  if (!box || !grid || grid.dataset.sg) return;
  grid.dataset.sg = '1';
  const run = () => { grid.classList.remove('is-run'); void grid.offsetWidth; grid.classList.add('is-run'); };
  box.addEventListener('pointerdown', () => { run(); });
  box.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); run(); }
  });
  run();
}
